import {STORES,H72,getStore,initialState,nowFor,stats,inWindow,expire,support,claim,credential,checkToken,lock,report,refund,settle} from './model.mjs';
const KEY='mealforward-demo-v1';
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.schema!==1)state=initialState();}catch{state=initialState();}
let filter='all',checkoutQty=1,currentStore='qinghe',checkedCoupon=null,credentialTimer=null,toastTimer=null;
const main=document.querySelector('#main'),dialog=document.querySelector('#dialog'),body=document.querySelector('#dialog-body');
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=t=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(t);
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('浏览器存储不可用，当前体验将在关闭页面后清除。');}};
const btn=(text,action,id='',style='')=>`<button class="button ${style}" data-action="${action}" data-id="${e(id)}">${text}</button>`;
const notice=(s,warning=false)=>`<div class="notice ${warning?'warning':''}">${s}</div>`;
const error=s=>{const el=document.querySelector('#form-error');if(el)el.textContent=s;else toast(s);};
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('toast-visible'),4000);}
function modal(html){clearInterval(credentialTimer);body.innerHTML=html;if(!dialog.open)dialog.showModal();}
function close(){dialog.close();clearInterval(credentialTimer);checkedCoupon=null;}
const pageHead=(title,sub,crumb='')=>`<div class="breadcrumb"><a href="#home">留膳首页</a> / ${crumb||title}</div><div class="page-heading"><h1>${title}</h1><p>${sub}</p></div>`;
const errorBox='<p class="error" id="form-error" role="alert"></p>';
function storeCard(s){const t=stats(state,s.id),c=state.configs[s.id],available=c.active&&!c.paused&&t.A>0;return `<article class="store-card"><a class="store-photo" style="display:block" href="#store/${s.id}" aria-label="了解${s.name}"><img src="/assets/${s.image}" alt="${e(c.meal)}餐食示意" loading="lazy"><div class="store-tag"><span>模拟小店</span><span>${s.type==='meat'?'家常荤食':'时蔬轻食'}</span></div><span class="store-number">${s.english}</span></a><div class="store-body"><div class="store-heading"><h3><a href="#store/${s.id}">${s.name}</a></h3><span>${s.area}</span></div><p class="store-description">${s.description}</p><p class="meal-name">${e(c.meal)} <span class="version">· v${c.version}</span></p><div class="store-time"><span>◷</span> ${s.windowLabel}</div><div class="progress-heading"><span>累计最终付款 <b>${t.F}</b> / 10 份 <small>· 模拟</small></span><span>${c.paused?'安全暂停':!c.active?'已下架':t.A+' 份可领取'}</span></div><div class="progress"><div style="width:${t.F*10}%"></div></div><div class="store-bottom"><div class="price"><strong>${c.price.toFixed(2)}</strong><small>测试 USDC / 份</small></div>${btn('留下一餐 <span>↗</span>','support',s.id,t.F>=10||!c.active||c.paused?'outline':'')}</div><button class="text-button claim-link" style="width:100%" data-action="claim" data-id="${s.id}" ${available?'':'disabled'}>${available?'需要一餐？免费领一份 →':'暂时没有可领取的餐份'}</button></div></article>`;}
function home(){const t=stats(state);main.innerHTML=`<div class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="seed">✳</span> 把善意留给下一餐</div><h1>一份热饭，<br>让<span>善意</span>接着发生。</h1><p>你留下一餐，小店认真准备。<br>让需要的人，不必解释，也能好好吃饭。</p><div class="hero-ctas"><a class="button" href="#stores">我想支持一餐 <span>↗</span></a><button class="button outline" data-action="choose-claim">我需要一餐 <span>→</span></button></div><div class="hero-note">领餐不需要钱包 · 无需说明个人处境</div></div><figure class="hero-visual"><img class="hero-image" src="/assets/hero-meal.jpg" alt="一份米饭、鸡腿与青菜组成的温暖家常餐食" fetchpriority="high"><div class="round-stamp"><small>GOOD FOOD</small><strong>留一份</strong><small>PASS IT FORWARD</small></div><figcaption class="photo-caption"><span class="heart">♡</span><div><strong>这一餐，留给下一位。</strong><small>一份支持，一次温暖的接力</small></div></figcaption><span class="visual-label">餐食视觉示意 · 非真实供餐</span></figure></section><div class="summary-strip"><div class="summary-intro">小小一餐，慢慢传递。</div><div class="summary-item"><strong>3<small>家</small></strong><small>各自独立的<br>模拟小店</small></div><div class="summary-item"><strong>${t.F}<small>份</small></strong><small>累计最终付款<br>演示样本</small></div><div class="summary-item"><strong>72<small>h</small></strong><small>一份餐券的<br>原始有效期</small></div></div><section class="section" id="stores"><div class="section-head"><div><div class="eyebrow">THE NEIGHBORHOOD TABLE</div><h2>把一餐，留在你喜欢的小店。</h2><p>三家小店，三种家常味道。同一份心意。</p></div><div class="filters" role="group" aria-label="按餐食类型筛选"><button data-action="filter" data-id="all" class="${filter==='all'?'selected':''}" aria-pressed="${filter==='all'}">全部小店</button><button data-action="filter" data-id="meat" class="${filter==='meat'?'selected':''}" aria-pressed="${filter==='meat'}">家常荤食</button><button data-action="filter" data-id="veg" class="${filter==='veg'?'selected':''}" aria-pressed="${filter==='veg'}">时蔬轻食</button></div></div><div class="store-grid">${STORES.filter(s=>filter==='all'||s.type===filter).map(storeCard).join('')}</div><p class="section-foot">每店累计支持上限 10 份 · 单次支持只属于一家店 · 测试资产没有真实美元价值</p></section></div><section class="how-section" id="how"><div class="container how-layout"><div class="how-intro"><div class="eyebrow">A LITTLE KINDNESS, FORWARD</div><h2>让一餐的暖意，<br>走到下一位。</h2><p>支持与领取，两条简单的路径。<br>每一份餐款，都有清楚的去向。</p></div><div class="how-steps"><div><div class="step-number">01</div><h3>选一家店，留下一餐</h3><p>选择套餐与份数。付款最终确认后，餐份才可被领取；你可以随时查看订单进度。</p></div><div><div class="step-number">02</div><h3>用邮箱，领一份餐券</h3><p>无需钱包。全平台同邮箱 72 小时内领取一份，餐券保留原有效期，可找回。</p></div><div><div class="step-number">03</div><h3>在供餐窗口，安心领餐</h3><p>72 小时内打开餐券，在公布窗口核券交餐。没有预约，老板本人确认并结算。</p></div></div></div></section><div class="container"><section class="ledger-teaser"><div><div class="eyebrow">EVERY MEAL, ACCOUNTED FOR</div><h2>善意有温度，餐账有来处。</h2><p>支持、领券、交餐、结算与返还，按店清楚呈现。</p></div><a class="button outline" href="#ledger">看看公开餐账 <span>↗</span></a></section><div class="closing">愿每一个平常的日子，都有一餐热饭。<span>A WARM MEAL. A KINDER DAY.</span></div></div>`;}
function detail(id){const s=getStore(id);if(!s)return missing();const c=state.configs[id],t=stats(state,id);main.innerHTML=`<div class="container page">${pageHead(s.name,s.description,'发现小店 / '+s.name)}<div class="detail-grid"><img class="detail-image" src="/assets/${s.image}" alt="${e(c.meal)}示意"><div class="detail-copy"><span class="pill">模拟商家 · ${s.area}</span><h2>${e(c.meal)}</h2><p class="muted">${s.detail}</p><div class="detail-facts"><div><small>当前原价 / 份</small><strong>${c.price.toFixed(2)} 测试 USDC</strong></div><div><small>累计最终付款 · 模拟</small><strong>${t.F} / 10 份</strong></div><div><small>午晚膳供餐窗口</small><strong style="font-size:12px">${s.windowLabel}</strong></div><div><small>可领取餐份</small><strong>${t.A} 份 · v${c.version}</strong></div></div><span class="pill">${c.paused?'安全暂停':c.active?'开放支持与领取':'套餐已下架'}</span><div class="detail-buttons">${btn('支持本店一餐 ↗','support',id)}${btn('免费领一份 →','claim',id,'outline')}</div>${notice('领券后 72 小时内，在供餐窗口到店。窗口是使用条件，无需预约。商家、餐食与交餐均为模拟。')}</div></div><section class="content-section"><h2>这份心意，如何传递？</h2><p>你的支持留在本店；最终确认后成为可领取的餐份。领取者通过邮箱获得一张原有效期 72 小时的餐券。老板确认模拟交餐并完成申报后，你的订单更新进度，老板本人再结算原价餐款。每单最多一张可拒收的感谢 NFT，不为每餐额外铸造。</p><a class="text-button" href="#ledger">查看本店餐账 →</a></section></div>`;}
function mine(tab='coupons'){const orders=state.orders.filter(o=>o.owner==='demo-wallet');main.innerHTML=`<div class="container page">${pageHead('我的餐券与订单','所有记录仅保存在这个浏览器；领券不需要钱包。')}<div class="tabs"><a href="#mine/coupons" class="${tab==='coupons'?'active':''}">我的餐券</a><a href="#mine/orders" class="${tab==='orders'?'active':''}">支持订单 ${orders.length?`(${orders.length})`:''}</a></div>${tab==='orders'?(state.wallet?orders.length?`<div class="order-list">${orders.slice().reverse().map(orderCard).join('')}</div>`:empty('还没有留下一餐','从你喜欢的小店开始，让一餐的暖意接着发生。','去发现小店','#stores'):empty('恢复你的体验钱包','本人订单与退款需要原付款钱包。这里使用明确标记的演示身份。','连接体验钱包',null,'wallet')):state.coupons.length?`<div class="order-list">${state.coupons.slice().reverse().map(c=>`<article class="order-card"><div class="order-top"><div><h3>${getStore(c.store).name} · ${e(c.meal)}</h3><small>${c.id} · v${c.version}</small></div><span class="pill">${couponStatus(c)}</span></div><p class="muted" style="margin-top:18px;font-size:12px">原有效期至 ${date(c.expires)} · 北京时间</p><div class="order-actions">${btn('打开我的券 →','coupon',c.id,'compact outline')}</div></article>`).join('')}</div>`:empty('一份热饭，给现在的你','无需说明个人处境。用邮箱领取，72 小时内使用。','选择一份餐',null,'choose-claim') }<div class="recovery-note"><button class="text-button" data-action="recover">使用原邮箱找回餐券 →</button></div>${notice('找回恢复原券、撤销旧核验入口，不会延长原 72 小时。演示不发送邮件，也不把邮箱上传到服务器。')}</div>`;}
function empty(title,sub,label,href,action){return `<div class="empty"><div class="empty-symbol">♧</div><h3>${title}</h3><p>${sub}</p>${href?`<a class="button" href="${href}">${label} →</a>`:btn(label+' →',action)}</div>`;}
function orderCard(o){const units=state.units.filter(u=>u.order===o.id);const count=k=>units.filter(u=>k.includes(u.status)).length;return `<article class="order-card"><div class="order-top"><div><h3>${getStore(o.store).name} · ${e(o.meal)}</h3><small>${o.id} · ${date(o.time)} · 原套餐 v${o.version}</small></div><span class="pill">付款最终确认 · 模拟</span></div><div class="order-metrics"><div><strong>${o.quantity}</strong><small>支持份数</small></div><div><strong>${count('HS')}</strong><small>已申报交餐</small></div><div><strong>${count('AR')}</strong><small>待处理餐份</small></div><div><strong>${count('X')}</strong><small>已安全返还</small></div></div><p class="muted" style="font-size:11px">原价 ${o.price} 测试 USDC / 份 · 待结算 ${count('H')*o.price} · 已到账 ${count('S')*o.price}</p><div class="order-actions">${btn('退自由份额 ('+count('A')+')','refund',o.id,'compact outline')}<button class="text-button" data-action="thanks" data-id="${o.id}">查看感谢反馈 →</button></div><div class="thank-card"><div><h3>谢谢你，留下一餐。</h3><p>${o.nft==='queued'?'感谢 NFT 资格已保留 · 技术接入前暂停铸造':o.nft==='hidden'?'感谢卡已在应用内隐藏':o.nft?'感谢卡历史示意':'已选择拒收 NFT · 感谢与餐款进度依然可看'}</p></div><span class="thank-mark">膳</span></div></article>`;}
const couponStatus=c=>({issued:'待使用',locked:'已锁定 · 待申报',reported:'已申报交餐',expired:'已到期'}[c.status]||'待核');
function couponPage(id){const c=state.coupons.find(c=>c.id===id);if(!c)return missing();const s=getStore(c.store);main.innerHTML=`<div class="container page"><div class="breadcrumb"><a href="#mine">我的餐券</a> / ${c.id}</div><article class="coupon"><div class="coupon-head"><small>MEALFORWARD · 留给你的一餐</small><h2>${s.name}</h2><p>${e(c.meal)}</p></div><div class="coupon-body"><span class="pill">${couponStatus(c)}</span><div class="coupon-meta"><span>一份餐食</span><span>原价 ${c.price} 测试 USDC · v${c.version}</span></div><div class="dashed"><p style="font-size:12px">原有效期至 <strong>${date(c.expires)}</strong></p><p class="muted" style="font-size:11px;margin-top:9px">供餐窗口 ${s.windowLabel} · 北京时间</p></div>${c.status==='issued'?btn('打开短时核验凭证 →','credential',c.id,'full'):notice(c.status==='locked'?'本券已被唯一锁定。超时不自动删除交餐责任，请在老板工作台核查原操作。':c.status==='expired'?'原 72 小时已结束，未锁餐份已安全回收。':'这份模拟餐食已申报。谢谢你好好照顾自己。')} ${notice('凭证只在供餐窗口内生成，最长 120 秒。检查不花券；本店老板锁定并确认交餐后才申报。')}<div class="recovery-note"><button class="text-button" data-action="recover">原邮箱找回 →</button></div></div></article></div>`;}
function ledger(){const t=stats(state);const amount=k=>state.units.filter(u=>k.includes(u.status)).reduce((n,u)=>n+u.price,0);main.innerHTML=`<div class="container page">${pageHead('每一餐，都有清楚的去向。','按店查看支持、发行、交餐与餐款流向。公开餐账不展示邮箱或私密核验凭证。','公开餐账')}<div class="status-line">演示样本 + 当前浏览器操作 · 观察时间 ${date(nowFor(state))}（北京时间）· 未连接链上索引</div><div class="ledger-stats">${[['累计支持',t.F,'份 · 最终付款模拟'],['当前已占领券',t.R,'份 · 待交餐'],['申报待付',t.H,amount('H')+' 测试 USDC'],['已付老板',t.S,amount('S')+' 测试 USDC'],['安全返还',t.X,amount('X')+' 测试 USDC']].map(([a,b,c])=>`<div class="stat"><small>${a}</small><strong>${b}</strong><small>${c}</small></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>模拟小店</th><th>累计支持 F</th><th>自由餐份 A</th><th>已领待用 R</th><th>申报待付 H</th><th>已付 S</th><th>返还 X</th></tr></thead><tbody>${STORES.map(s=>{const x=stats(state,s.id);return `<tr><td><a href="#store/${s.id}">${s.name}</a><small>累计上限 10 份</small></td>${['F','A','R','H','S','X'].map(k=>`<td>${x[k]} <small>${x[k]?(state.units.filter(u=>u.store===s.id&&(k==='F'||u.status===k)).reduce((n,u)=>n+u.price,0))+' 测试 USDC':'—'}</small></td>`).join('')}</tr>`;}).join('')}</tbody></table></div>${notice('账目恒等式：F = A + R + H + S + X。发行累计 '+state.coupons.length+' 张（不含初始样本），未知操作 0（演示）。退款与使用均不恢复累计销售上限；NFT 不增加资金桶。')}<section class="activity"><h2 style="font-size:25px;margin-bottom:15px">最近的暖意接力</h2>${state.events.length?state.events.slice(0,12).map(v=>`<div class="activity-row"><small>${date(v.time)}</small><span>${getStore(v.store).name} · ${v.label}</span><span>${v.qty} 份</span></div>`).join(''):'<p class="muted" style="font-size:12px;padding:20px 0">还没有新的体验操作。你可以支持一餐，观察餐账如何变化。</p>'}</section><section class="content-section"><h2>透明，也保留边界。</h2><p>真实实现中，付款钱包、金额、门店与业务事件会公开；邮箱、恢复秘密与餐券核验凭证仅保留在受限后台。公共感谢卡只记录历史感谢，不能用来查看他人的订单、餐券或退款权限。</p><a href="#about" class="text-button">了解演示与隐私边界 →</a></section></div>`;}
function merchant(){const s=getStore(currentStore),c=state.configs[currentStore],t=stats(state,currentStore),auth=state.merchant===currentStore;main.innerHTML=`<div class="container page">${pageHead('把每一餐，认真交到手里。','本店老板工作台 · 连接钱包与认证是两个独立步骤。','商家工作台')}<div class="merchant-nav"><select class="select" id="merchant-store" aria-label="切换模拟门店">${STORES.map(s=>`<option value="${s.id}" ${s.id===currentStore?'selected':''}>${s.name} · 模拟店</option>`).join('')}</select><span class="pill">${auth?'本店演示身份已认证':'未认证'}</span>${btn(auth?'退出本店身份':'认证本店演示身份','merchant-auth',currentStore,'compact outline')}</div>${auth?`<div class="merchant-grid"><section class="panel"><h3>核券与模拟交餐</h3><p>扫描二维码，或粘贴同一高熵核验串。检查不消耗餐券，也不产生付款。</p><div class="form-field"><label for="token-input">短时核验串</label><input id="token-input" autocomplete="off" placeholder="粘贴餐券内的 120 秒凭证"></div>${errorBox}<div style="display:flex;gap:12px">${btn('检查凭证 →','check-token',currentStore)}${btn('相机扫码','camera',currentStore,'outline')}</div><div id="scanner"></div><div id="checked-result"></div>${state.coupons.filter(c=>c.store===currentStore&&c.status==='locked').map(c=>notice(`原锁定案件 ${c.id}：${e(c.meal)}。${btn('确认交餐并申报','report',c.id,'compact outline')}`)).join('')}</section><section class="panel"><h3>原价应付与本人结算</h3><div class="order-metrics"><div><strong>${t.H}</strong><small>申报待付份数</small></div><div><strong>${state.units.filter(u=>u.store===currentStore&&u.status==='H').reduce((n,u)=>n+u.price,0)}</strong><small>应付测试 USDC</small></div></div><p>按每份原套餐版本的价格核算。结算由本店老板本人确认；已到账 ${state.units.filter(u=>u.store===currentStore&&u.status==='S').reduce((n,u)=>n+u.price,0)} 测试 USDC（模拟）。</p>${btn('本人确认结算 →','settle',currentStore)}${notice('无平台分成。扫码检查与唯一锁定均不等于交餐申报。')}</section><section class="panel"><h3>本店套餐 · v${c.version}</h3><p>${e(c.meal)} · 原价 ${c.price} 测试 USDC / 份</p><p style="margin-top:8px">累计支持 ${t.F}/10 份，各内容版本共用上限。</p><div style="display:flex;gap:12px;flex-wrap:wrap">${btn('编辑新版本草稿','edit-menu',currentStore,'outline')}${btn(c.active?'下架套餐':'重新上架','toggle-active',currentStore,'outline')}</div>${notice('发布未来版本不会改变已付款旧券的原价、内容与供餐规则。下架停止新增，旧餐券与待付款责任保留。')}</section><section class="panel"><h3>运行与安全状态</h3><p>供餐窗口 ${s.windowLabel} · 北京时间</p><p style="margin-top:8px">${inWindow(s,nowFor(state))?'当前处于供餐窗口':'当前不在供餐窗口'} · ${date(nowFor(state))}</p>${btn(c.paused?'解除模拟安全暂停':'安全暂停','toggle-pause',currentStore,'outline')}${btn('切换至演示午膳时间','demo-clock',currentStore,'outline')}${state.clockOffset?btn('恢复实际时钟','real-clock','','outline'):''}${notice('演示时钟只改变本机模拟时间。锁定的责任不会因超时自动清除。')}</section></div>`:empty('先认证，再管理这家店','演示签名只用于当前门店身份，不调用真实钱包。','认证本店身份',null,'merchant-auth')}${notice('三店为独立开发者控制多个钱包的工程演示，不代表真实合作商家或独立运营机构。')}</div>`;}
function about(){main.innerHTML=`<div class="container page">${pageHead('先把规则说清楚。','留膳 MealForward · 三店演示 MVP','演示说明')}<div class="about-grid"><section><div class="eyebrow">WHAT YOU CAN EXPERIENCE</div><h2>小范围体验，完整的心意。</h2><p>网站以用户提供的《三店演示 MVP》为规则来源。青禾小馆、拾光食堂与暖巷饭铺均为虚构店名，餐食摄影仅作视觉示意。你可以浏览、模拟支持、领取餐券、找回、核券、交餐与结算，并观察餐账。</p></section><section><div class="eyebrow">CURRENT BOUNDARY</div><h2>每一步模拟，都明确可见。</h2><p>当前为浏览器交互原型，没有部署合约、连接真实钱包、发送邮件或铸造 NFT。原型使用本机演示身份与本地数据。真实 Monad Testnet、单测试 USDC、MON Gas、认证、存储与容量测试仍待技术验证。</p></section></div><section class="content-section faq"><h2>关于这一餐，你可能想知道</h2>${[
['领取一餐需要什么？','选择有自由餐份的店，用邮箱完成演示验证。同一邮箱全平台 72 小时内一次一份；原餐券 72 小时内在公布供餐窗口使用。无需钱包，无需说明个人处境。本演示不发邮件，不代表真实邮箱核验。'],
['可以预约、改期或延长餐券吗？','不提供预约、时段选择、改期或 30 分钟备餐预约。供餐窗口只是使用条件。刷新、找回或取消旧核验入口均不会重开原 72 小时。'],
['支持后，什么份额可以退款？','只有原付款钱包未占用的自由餐份可安全退款。已领、已锁或已交餐的责任保留；退款、使用和回收均不恢复每店累计支持 10 份的上限。没有自动七日退款。'],
['一单支持三份，会收到几张 NFT？','每个最终付款订单最多一张可拒收的支持感谢 NFT；交餐进度显示在原付款人的订单，不逐餐铸造。商家可自愿接受一张欢迎卡，不能用作资质认证。当前仅展示样卡，未真实铸造。'],
['感谢 NFT 会公开什么？','候选为共享固定 IPFS 感谢图文、永久不可转移。它记录历史感谢，可能对应已退款订单。公开卡不包含领取者信息，也不能开放私密 API。已铸造卡只能在应用内隐藏，不能保证删除链上历史或 IPFS 副本。'],
['我的邮箱与餐券在哪里？','这个原型不把邮箱传到服务器，仅在浏览器本地保存不可直接阅读的摘要用于模拟频次与找回；核验秘密仅留在本机。真实方案需要受限数据库与服务端认证，本机隔离不能作为生产安全证明。点击页脚「重置体验」即可清除演示数据。'],
['图片与测试数据说明','主视觉为 AI 生成餐食摄影；时蔬图为 Unsplash 示意摄影。初始样本为三店累计 6、4、3 份，每店含 1 份已付与 1 份申报待付。它们不是实际需求、供餐或链上交易证据。全部真实钱包、NFT、Gas、合约与并发测试仍未进行。']
].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>${notice('当前不需要提供私钥、转账或真实个人处境资料。测试币没有真实美元价值；图文存储不承诺永久可用。')}</div>`;}
function publicCard(){main.innerHTML=`<div class="container page">${pageHead('一张感谢，一段暖意。','公共感谢图文样卡 · 未铸造，不含私人订单权限。','NFT 公开查看')}<div class="public-card"><div class="eyebrow" style="justify-content:center">MEALFORWARD · SUPPORT</div><div class="thank-mark">膳</div><h2>谢谢你，支持留膳。</h2><p>愿你留下一餐的心意，<br>成为下一位平常日子里的暖意。</p><small>公共历史感谢 · 样卡 / 无链上 token<br>原订单可能已退款 · 当前餐款进度请回本人订单</small></div><div style="text-align:center;margin-top:25px"><a class="button outline" href="#mine/orders">查看本人订单 →</a></div></div>`;}
function missing(){main.innerHTML=`<div class="container page">${empty('这一页还没有上桌','这个入口不存在，回到小店重新开始。','返回首页','#home')}</div>`;}
function render(scroll=false){expire(state,nowFor(state));save();const [route,id]=location.hash.slice(1).split('/');document.querySelector('#wallet-button').innerHTML=state.wallet?'体验钱包已连接 <span>✓</span>':'体验钱包 <span>↗</span>';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route));clearInterval(credentialTimer);if(route==='store')detail(id);else if(route==='mine')mine(id||'coupons');else if(route==='coupon')couponPage(id);else if(route==='ledger')ledger();else if(route==='merchant')merchant();else if(route==='about')about();else if(route==='nft')publicCard();else{home();if(route==='stores'||route==='how')requestAnimationFrame(()=>document.querySelector('#'+route)?.scrollIntoView({behavior:'auto'}));}if(scroll&&!['stores','how'].includes(route)){window.scrollTo(0,0);main.focus({preventScroll:true});}}
function wallet(){modal(`<h2 id="dialog-title">轻轻开始，留下一餐。</h2><p class="dialog-subtitle">连接与签名均为本机模拟，不调用真实钱包。</p><div class="detail-facts"><div><small>目标网络</small><strong>Monad Testnet</strong></div><div><small>本次身份</small><strong>体验付款钱包</strong></div></div>${notice('真实付款将需要授权 USDC 与确认付款两步。当前不会广播交易、花费 USDC 或 MON。')}${errorBox}${btn(state.wallet?'恢复原体验钱包':'连接体验钱包 →','connect','','full')}`);}
function supportModal(id){const s=getStore(id),c=state.configs[id],t=stats(state,id);if(!c.active||c.paused||t.F>=10)return toast('本店目前不接受新的支持。');checkoutQty=1;modal(`<h2 id="dialog-title">把一餐，留在${s.name}。</h2><p class="dialog-subtitle">一单一店、一种测试资产。付款前查看全部信息。</p><div class="checkout-item"><img src="/assets/${s.image}" alt="${e(c.meal)}"><div><h3>${e(c.meal)}</h3><p>原价 ${c.price} 测试 USDC · 内容版本 v${c.version}</p></div></div><div class="checkout-row"><span>支持份数 · 还可支持 ${10-t.F} 份</span><div class="quantity"><button data-action="qty-minus" aria-label="减少份数">−</button><span id="quantity-value">1</span><button data-action="qty-plus" data-id="${id}" aria-label="增加份数">+</button></div></div><div class="checkout-row checkout-total"><span>模拟付款合计</span><strong><span id="checkout-total">${c.price.toFixed(2)}</span> <small>测试 USDC</small></strong></div><label class="checkbox"><input type="checkbox" id="nft-opt-in" checked><span>接受一张公开、不可转移的支持感谢 NFT。每单最多一张；不含领取者信息，也不保证餐款未退款。可取消勾选。</span></label><p class="form-help">餐款全额留在本店。真实流程 Gas 以 MON 另付，当前费率未核定；感谢卡无需额外付款或铸造签名。</p>${errorBox}${btn(state.wallet?'确认模拟授权与付款 →':'先连接体验钱包 →',state.wallet?'pay':'support-wallet',id,'full')}${notice('这是一笔模拟操作，不会请求真实签名。感谢 NFT 暂停铸造，付款后可在订单查看进度。')}`);}
async function pay(id){const nft=document.querySelector('#nft-opt-in')?.checked;const qty=checkoutQty;const c=state.configs[id];modal(`<h2 id="dialog-title">正在传递这一餐。</h2><p class="dialog-subtitle">${qty} 份 · ${qty*c.price} 测试 USDC · ${getStore(id).name}</p><div class="flow"><span class="current" id="flow1">01 模拟授权</span><span id="flow2">02 模拟付款</span><span id="flow3">03 最终确认</span></div><p class="muted" id="flow-message" style="font-size:12px">演示授权中。授权本身不代表付款完成。</p>`);await new Promise(r=>setTimeout(r,600));if(!dialog.open)return;document.querySelector('#flow1').className='done';document.querySelector('#flow2').className='current';document.querySelector('#flow-message').textContent='模拟付款已提交，等待最终确认。';await new Promise(r=>setTimeout(r,700));if(!dialog.open)return;try{const o=support(state,id,qty,nft,nowFor(state));save();render();modal(`<div class="success-mark">✓</div><h2 id="dialog-title">${qty} 份暖意，已留下。</h2><p class="dialog-subtitle">模拟付款最终确认，餐份已成为本店可领份额。</p><div class="checkout-row"><span>订单</span><strong>${o.id}</strong></div><div class="checkout-row"><span>合计</span><strong>${qty*c.price} 测试 USDC</strong></div>${notice(nft?'感谢卡资格已保留，实际铸造暂停。它不影响订单进度。':'已拒收感谢 NFT，你仍可查看感谢文字与订单进度。')}${btn('查看本人订单 →','go-orders','','full')}`);}catch(err){close();toast(err.message);}}
function chooseClaim(){modal(`<h2 id="dialog-title">选一份餐，好好吃饭。</h2><p class="dialog-subtitle">无需钱包，也无需说明个人处境。</p>${STORES.map(s=>{const a=stats(state,s.id).A,c=state.configs[s.id];return `<div class="checkout-item"><img src="/assets/${s.image}" alt="${e(c.meal)}"><div style="flex:1"><h3>${s.name}</h3><p>${e(c.meal)} · ${a} 份可领</p></div><button class="button compact outline" data-action="claim" data-id="${s.id}" ${a&&c.active&&!c.paused?'':'disabled'}>选这份 →</button></div>`;}).join('')}`);}
function claimModal(id){const s=getStore(id);if(stats(state,id).A<1||!state.configs[id].active||state.configs[id].paused)return toast('本店暂时没有可领取的餐份。');modal(`<h2 id="dialog-title">${s.name}，为你留一餐。</h2><p class="dialog-subtitle">一份餐券，原有效期 72 小时。</p><div class="form-field"><label for="email-input">你的邮箱</label><input type="email" id="email-input" placeholder="name@example.com" autocomplete="email" required><p class="form-help">本机模拟验证，不发送邮件；仅保存本机摘要用于频次与找回。</p></div>${notice('全平台同邮箱 72 小时内只能领一份。原券期内存在午晚膳窗口；不预约、不延长原券。')}<label class="checkbox"><input type="checkbox" id="claim-consent"><span>我了解这是演示，不是真实供餐。餐券需在公布供餐窗口内使用。</span></label>${errorBox}${btn('模拟验证邮箱并领一份 →','issue',id,'full')}`);}
async function emailHash(){const input=document.querySelector('#email-input');if(!input.checkValidity()){input.reportValidity();throw Error('请输入有效的邮箱地址。');}const value=input.value.trim().toLowerCase();const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('');}
async function issue(id){if(!document.querySelector('#claim-consent')?.checked)return error('请先确认演示与供餐窗口说明。');try{const hash=await emailHash(),c=claim(state,id,hash,nowFor(state));save();modal(`<div class="success-mark">✓</div><h2 id="dialog-title">这一餐，给现在的你。</h2><p class="dialog-subtitle">${getStore(id).name} · ${e(c.meal)}</p><div class="detail-facts"><div><small>原有效期至</small><strong style="font-size:12px">${date(c.expires)}</strong></div><div><small>使用条件</small><strong style="font-size:12px">公布供餐窗口内</strong></div></div>${notice('演示邮箱验证与发行已完成。找回、刷新不会延长券期。')} ${btn('打开我的餐券 →','open-coupon',c.id,'full')}`);render();}catch(err){error(err.message);}}
function recoverModal(){modal(`<h2 id="dialog-title">把原来那一餐找回来。</h2><p class="dialog-subtitle">使用原邮箱，恢复同一张券，不重开 72 小时。</p><div class="form-field"><label for="email-input">原领取邮箱</label><input id="email-input" type="email" autocomplete="email" placeholder="name@example.com" required></div>${notice('仅找回这个浏览器中的演示记录。成功后撤销旧短时凭证。')}${errorBox}${btn('模拟验证并找回 →','recover-submit','','full')}`);}
async function recover(){try{const hash=await emailHash(),c=state.coupons.slice().reverse().find(c=>c.emailHash===hash);if(!c)throw Error('本机没有这个邮箱的餐券记录，请确认原邮箱与浏览器。');c.token=null;c.tokenExpires=0;save();close();location.hash='coupon/'+c.id;render();toast('原券已恢复，旧核验入口已撤销；原有效期不变。');}catch(err){error(err.message);}}
function showCredential(id){const c=state.coupons.find(c=>c.id===id);try{const token=credential(state,c,nowFor(state));save();modal(`<h2 id="dialog-title">向本店老板出示。</h2><p class="dialog-subtitle">${getStore(c.store).name} · ${e(c.meal)} · 仅本店可用</p><div class="qr-wrap"><div id="qr-code" style="display:flex;justify-content:center;margin:24px 0" aria-label="当前短时核验二维码"></div><small id="credential-countdown"></small></div>${btn('复制同一核验串','copy-token',id,'full outline')}${notice('二维码与复制串是同一短时凭证，最长 120 秒。请勿公开分享。检查不花券、不付款。')}`);new window.QRCode(document.querySelector('#qr-code'),{text:token,width:210,height:210,colorDark:'#234c3d',colorLight:'#ffffff',correctLevel:window.QRCode.CorrectLevel.M});const tick=()=>{const remain=Math.max(0,Math.ceil((c.tokenExpires-nowFor(state))/1000));const el=document.querySelector('#credential-countdown');if(el)el.textContent=remain?'凭证剩余 '+remain+' 秒 · 不超原券期与窗口':'凭证已失效，请关闭后重新生成';if(!remain)clearInterval(credentialTimer);};tick();credentialTimer=setInterval(tick,1000);}catch(err){modal(`<h2 id="dialog-title">稍等一个供餐窗口。</h2><p class="dialog-subtitle">${e(err.message)}</p>${notice('窗口 '+getStore(c.store).windowLabel+' · 北京时间。餐券原有效期至 '+date(c.expires)+'。')}${btn('返回餐券','close','','full outline')}<p class="form-help">想体验核券流程，可在商家工作台把演示时钟切至午膳窗口。</p>`);}}
function thanks(id){const o=state.orders.find(o=>o.id===id);modal(`<h2 id="dialog-title">谢谢你，支持留膳。</h2><p class="dialog-subtitle">感谢属于历史，进度回到原订单。</p><div class="thank-card"><div><h3>把暖意，留给下一餐。</h3><p>一单 ${o.quantity} 份支持 · 不逐餐铸造</p></div><span class="thank-mark">膳</span></div>${notice('公共感谢卡永久不可转移，可能对应已退款订单。当前样卡未铸造；不会生成领取者名字、邮箱或来信。')}<a class="text-button" href="#nft" data-action="close">查看公共图文样卡 →</a>${o.nft==='queued'?btn('停止尚未接受的 NFT 任务','stop-nft',id,'full outline'):''}`);}
function refundModal(id){const o=state.orders.find(o=>o.id===id),u=state.units.filter(u=>u.order===id&&u.status==='A');if(!u.length)return toast('没有可安全退款的自由份额。');modal(`<h2 id="dialog-title">返还还未被领取的餐款。</h2><p class="dialog-subtitle">${getStore(o.store).name} · 原订单 ${o.id}</p><div class="checkout-row"><span>自由份额</span><strong>${u.length} 份</strong></div><div class="checkout-row checkout-total"><span>模拟返还原付款钱包</span><strong>${u.length*o.price} <small>测试 USDC</small></strong></div>${notice('已领、已锁或已交餐的份额不能撤回。退款不恢复累计支持上限。历史感谢卡与付款记录仍保留。')}${errorBox}${btn('确认安全返还 →','refund-confirm',id,'full')}`);}
function authMerchant(id){currentStore=id||currentStore;if(state.merchant===currentStore){state.merchant=null;save();render();return toast('已退出本店演示身份。');}modal(`<h2 id="dialog-title">认证${getStore(currentStore).name}身份。</h2><p class="dialog-subtitle">只认证当前店，不获得其他门店权限。</p>${notice('连接地址不是登录。此按钮模拟老板本人签名认证，不调用真实钱包；生产身份验证尚未接入。')} ${btn('模拟本人签名并认证 →','merchant-auth-confirm',currentStore,'full')}`);}
function checkCredential(){try{const token=document.querySelector('#token-input').value.trim();checkedCoupon=checkToken(state,currentStore,token,nowFor(state));document.querySelector('#checked-result').innerHTML=notice(`检查通过：${e(checkedCoupon.meal)} · 原价 ${checkedCoupon.price} 测试 USDC · v${checkedCoupon.version}。本次检查未消费餐券。${btn('唯一锁定这张券 →','lock',checkedCoupon.id,'compact outline')}`);error('');}catch(err){checkedCoupon=null;document.querySelector('#checked-result').innerHTML='';error(err.message);}}
function editMenu(id){if(state.merchant!==id)return toast('请先认证本店身份。');const c=state.configs[id];modal(`<h2 id="dialog-title">下一版套餐，先存草稿。</h2><p class="dialog-subtitle">${getStore(id).name} · 当前 v${c.version} → 新版本 v${c.version+1}</p><div class="form-field"><label for="menu-name">新套餐名称</label><input id="menu-name" maxlength="30" value="${e(c.draft?.meal||c.meal)}"></div><div class="form-field"><label for="menu-price">未来原价 · 测试 USDC / 份</label><input id="menu-price" type="number" min="1" max="100" step="0.01" value="${c.draft?.price||c.price}"></div>${notice('未来新支持使用新版本，已付款订单与旧券保持原价格和餐食内容。')} ${errorBox}<div style="display:flex;gap:12px">${btn('保存草稿','save-draft',id,'outline')}${btn('确认发布新版本','publish-menu',id)}</div>`);}
function draft(id,publish){if(state.merchant!==id)return error('请先认证本店身份。');const meal=document.querySelector('#menu-name').value.trim(),price=Number(document.querySelector('#menu-price').value);if(!meal||!Number.isFinite(price)||price<1||price>100)return error('请填写套餐名称，以及 1–100 的有效原价。');const c=state.configs[id];c.draft={meal,price};if(publish){c.meal=meal;c.price=price;c.version++;delete c.draft;}save();close();render();toast(publish?'新版本已发布；旧订单与旧券原价不变。':'草稿已保存，尚未对新支持生效。');}
let cameraStream=null,cameraFrame=null;
async function stopCamera(){if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;if(cameraFrame)cancelAnimationFrame(cameraFrame);cameraFrame=null;}
async function camera(){if(!('BarcodeDetector' in window))return toast('当前浏览器不支持二维码识别，请复制并粘贴同一核验串。');try{await stopCamera();cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const target=document.querySelector('#scanner');target.innerHTML='<video id="scan-video" autoplay playsinline style="width:100%;margin-top:20px;border-radius:6px"></video><button class="text-button" data-action="stop-camera">关闭相机</button>';const video=document.querySelector('#scan-video');video.srcObject=cameraStream;await video.play();const detector=new window.BarcodeDetector({formats:['qr_code']});const tick=async()=>{if(!cameraStream)return;const values=await detector.detect(video);if(values.length){document.querySelector('#token-input').value=values[0].rawValue;await stopCamera();target.innerHTML='';checkCredential();}else cameraFrame=requestAnimationFrame(tick);};cameraFrame=requestAnimationFrame(tick);}catch(err){await stopCamera();toast('无法打开相机，请使用复制核验串。');}}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;try{
 if(a==='close')close();else if(a==='wallet')wallet();else if(a==='connect'){state.wallet=true;save();close();render();toast('体验钱包已恢复；未连接真实钱包。');}
 else if(a==='support')supportModal(id);else if(a==='support-wallet'){state.wallet=true;save();el.dataset.action='pay';el.textContent='确认模拟授权与付款 →';document.querySelector('#wallet-button').innerHTML='体验钱包已连接 <span>✓</span>';toast('已连接本机体验钱包。');}else if(a==='pay')await pay(id);
 else if(a==='qty-minus'||a==='qty-plus'){checkoutQty=Math.max(1,Math.min(a==='qty-plus'?10-stats(state,id).F:checkoutQty,checkoutQty+(a==='qty-plus'?1:-1)));document.querySelector('#quantity-value').textContent=checkoutQty;const routeId=id||body.querySelector('[data-action="qty-plus"]').dataset.id;document.querySelector('#checkout-total').textContent=(checkoutQty*state.configs[routeId].price).toFixed(2);}
 else if(a==='go-orders'){close();location.hash='mine/orders';render();}else if(a==='choose-claim')chooseClaim();else if(a==='claim')claimModal(id);else if(a==='issue')await issue(id);
 else if(a==='open-coupon'){close();location.hash='coupon/'+id;render();}else if(a==='coupon'){location.hash='coupon/'+id;render();}else if(a==='credential')showCredential(id);
 else if(a==='copy-token'){const c=state.coupons.find(c=>c.id===id);if(c.tokenExpires<=nowFor(state))throw Error('凭证已失效，请重新生成。');await navigator.clipboard.writeText(c.token);toast('同一短时核验串已复制。');}
 else if(a==='recover')recoverModal();else if(a==='recover-submit')await recover();else if(a==='refund')refundModal(id);else if(a==='refund-confirm'){const n=refund(state,id,nowFor(state));save();close();render();toast(n+' 份自由餐款已模拟返还原钱包。');}
 else if(a==='thanks')thanks(id);else if(a==='stop-nft'){state.orders.find(o=>o.id===id).nft=false;save();close();render();toast('尚未接受的 NFT 任务已停止。');}
 else if(a==='filter'){filter=id;const y=window.scrollY;home();window.scrollTo(0,y);}
 else if(a==='merchant-auth')authMerchant(id);else if(a==='merchant-auth-confirm'){state.merchant=id;currentStore=id;save();close();render();toast('本店演示身份已认证。');}
 else if(a==='check-token')checkCredential();else if(a==='lock'){const c=lock(state,currentStore,checkedCoupon?.token,nowFor(state));save();render();toast('已唯一锁定 '+c.id+'；尚未申报交餐。');}
 else if(a==='report'){const c=state.coupons.find(c=>c.id===id);modal(`<h2 id="dialog-title">确认这一餐已经交出。</h2><p class="dialog-subtitle">${e(c.meal)} · 原价 ${c.price} 测试 USDC</p>${notice('交餐申报最终成功后，原付款订单更新已申报进度，原价餐款转为老板待付。不会新增交餐 NFT。')} ${errorBox}${btn('确认模拟交餐并申报','report-confirm',id,'full')}`);}
 else if(a==='report-confirm'){report(state,state.coupons.find(c=>c.id===id),nowFor(state));save();close();render();toast('模拟交餐申报成功，原订单进度已更新。');}
 else if(a==='settle'){if(state.merchant!==id)throw Error('请认证本店老板身份。');const amount=state.units.filter(u=>u.store===id&&u.status==='H').reduce((n,u)=>n+u.price,0);if(!amount)throw Error('暂无待结算餐款。');modal(`<h2 id="dialog-title">本人确认，原价结算。</h2><p class="dialog-subtitle">${getStore(id).name} · ${amount} 测试 USDC</p>${notice('仅将已申报待付份额结算至本店原绑定老板钱包。无平台分成；此处模拟签名与到账。')}${btn('模拟本人签名并确认到账','settle-confirm',id,'full')}`);}
 else if(a==='settle-confirm'){const amount=settle(state,id,nowFor(state));save();close();render();toast(amount+' 测试 USDC 已模拟到账。');}
 else if(a==='toggle-active'||a==='toggle-pause'){if(state.merchant!==id)throw Error('请先认证本店。');const c=state.configs[id];if(a==='toggle-active')c.active=!c.active;else c.paused=!c.paused;save();render();toast(a==='toggle-active'?'本店上架状态已更新，原责任保留。':'安全状态已更新。');}
 else if(a==='edit-menu')editMenu(id);else if(a==='save-draft')draft(id,false);else if(a==='publish-menu')draft(id,true);
 else if(a==='demo-clock'){const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());state.clockOffset=Date.parse(day+'T12:00:00+08:00')-Date.now();save();render();toast('本机演示时钟已切至今天 12:00；餐券原有效期不变。');}
 else if(a==='real-clock'){state.clockOffset=0;save();render();toast('已恢复实际时钟。');}else if(a==='camera')await camera();else if(a==='stop-camera'){await stopCamera();document.querySelector('#scanner').innerHTML='';}
 else if(a==='reset')modal(`<h2 id="dialog-title">从新的一餐开始。</h2><p class="dialog-subtitle">清除这个浏览器中的所有体验订单、餐券和门店编辑，恢复初始模拟样本。</p>${notice('此操作只影响本机演示数据。')}${btn('确认重置体验','reset-confirm','','full')}`);
 else if(a==='reset-confirm'){await stopCamera();state=initialState();save();close();location.hash='home';render();toast('体验已重置，欢迎重新开始。');}
 }catch(err){error(err.message||'操作暂未完成，请重试原操作。');}});
document.addEventListener('change',event=>{if(event.target.id==='merchant-store'){stopCamera();currentStore=event.target.value;checkedCoupon=null;render();}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)close();}});
dialog.addEventListener('close',()=>clearInterval(credentialTimer));
window.addEventListener('hashchange',()=>{stopCamera();if(dialog.open)close();render(true);});
window.addEventListener('pagehide',stopCamera);
render();
